#include <cstdint>
#include <format>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

// Subsystem 1: turns raw text into numbers. Knows nothing about totals or reports.
class Loader {
 public:
  [[nodiscard]] std::vector<std::int32_t> load(std::string_view raw) const {
    std::vector<std::int32_t> values;
    std::istringstream stream{std::string(raw)};
    std::string field;
    while (std::getline(stream, field, ',')) values.push_back(std::stoi(field));
    return values;
  }
};

// Subsystem 2: turns numbers into one total. Knows nothing about text or reports.
class Processor {
 public:
  [[nodiscard]] std::int64_t total(const std::vector<std::int32_t>& values) const {
    std::int64_t sum = 0;
    for (const std::int32_t value : values) sum += value;
    return sum;
  }
};

// Subsystem 3: turns a total into a report line. Knows nothing about text or numbers.
class Saver {
 public:
  [[nodiscard]] std::string save(std::int64_t total) const { return std::format("total: {}", total); }
};

// The facade: one call, three subsystems coordinated in order.
class PipelineFacade {
 public:
  [[nodiscard]] std::string run(std::string_view raw) const { return saver_.save(processor_.total(loader_.load(raw))); }

 private:
  Loader loader_;
  Processor processor_;
  Saver saver_;
};

int main() {
  const PipelineFacade facade;
  std::cout << facade.run("10,20,30,40") << '\n';
}

