#include <format>
#include <iostream>

// Three subsystems, each with one job and its own order to be started in.
class PowerBus {
 public:
  [[nodiscard]] bool energize() {
    energized_ = true;
    return true;
  }
  [[nodiscard]] bool energized() const { return energized_; }

 private:
  bool energized_ = false;
};

class SensorBus {
 public:
  explicit SensorBus(const PowerBus& power) : power_(power) {}
  [[nodiscard]] bool start() {
    if (!power_.energized()) return false;  // needs power first
    started_ = true;
    return true;
  }
  [[nodiscard]] bool started() const { return started_; }

 private:
  const PowerBus& power_;
  bool started_ = false;
};

class MotionController {
 public:
  explicit MotionController(const SensorBus& sensors) : sensors_(sensors) {}
  [[nodiscard]] bool arm() {
    if (!sensors_.started()) return false;  // needs sensors reporting first
    armed_ = true;
    return true;
  }
  [[nodiscard]] bool armed() const { return armed_; }

 private:
  const SensorBus& sensors_;
  bool armed_ = false;
};

// Without a facade: every caller repeats the order and the failure handling.
[[nodiscard]] bool bring_up_by_hand(PowerBus& power, SensorBus& sensors, MotionController& motion) {
  if (!power.energize()) return false;
  if (!sensors.start()) return false;
  return motion.arm();
}

// The facade: one call, the same three subsystems, coordinated once.
class RobotFacade {
 public:
  RobotFacade() : sensors_(power_), motion_(sensors_) {}
  [[nodiscard]] bool bring_up() {
    if (!power_.energize()) return false;
    if (!sensors_.start()) return false;
    return motion_.arm();
  }

 private:
  PowerBus power_;
  SensorBus sensors_;
  MotionController motion_;
};

int main() {
  PowerBus power;
  SensorBus sensors(power);
  MotionController motion(sensors);
  std::cout << std::format("bring-up by hand:    {}\n", bring_up_by_hand(power, sensors, motion));

  RobotFacade facade;
  std::cout << std::format("bring-up via facade: {}\n", facade.bring_up());
}

#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <sstream>
#include <string>
#include <vector>

struct Sample {
  std::int64_t timestamp_ms;
  std::int32_t distance_mm;
};

struct Report {
  std::int64_t duration_ms;
  std::int32_t min_distance_mm;
  std::int32_t max_distance_mm;
  std::int64_t sample_count;
};

// Subsystem 1, loading: text in, samples out. Knows nothing about statistics or formatting.
class RunParser {
 public:
  [[nodiscard]] std::vector<Sample> parse(std::string_view raw_log) const {
    std::vector<Sample> samples;
    std::istringstream stream{std::string(raw_log)};
    std::string line;
    while (std::getline(stream, line)) {
      std::istringstream fields{line};
      std::string timestamp_text;
      std::string distance_text;
      std::getline(fields, timestamp_text, ',');
      std::getline(fields, distance_text, ',');
      samples.push_back(Sample{.timestamp_ms = std::stoll(timestamp_text), .distance_mm = std::stoi(distance_text)});
    }
    return samples;
  }
};

// Subsystem 2, processing: samples in, one report out, or nothing when there are no samples.
class RunStats {
 public:
  [[nodiscard]] std::optional<Report> analyze(std::span<const Sample> samples) const {
    if (samples.empty()) return std::nullopt;
    std::int32_t min_mm = samples.front().distance_mm;
    std::int32_t max_mm = samples.front().distance_mm;
    for (const Sample& sample : samples) {
      min_mm = std::min(min_mm, sample.distance_mm);
      max_mm = std::max(max_mm, sample.distance_mm);
    }
    return Report{.duration_ms = samples.back().timestamp_ms - samples.front().timestamp_ms,
                  .min_distance_mm = min_mm,
                  .max_distance_mm = max_mm,
                  .sample_count = std::ssize(samples)};
  }
};

// Subsystem 3, output: one report in, or nothing, one line out either way.
class ReportWriter {
 public:
  [[nodiscard]] std::string format(const std::optional<Report>& report) const {
    if (!report) return "no samples";
    return std::format("{} samples over {} ms, {} to {} mm", report->sample_count, report->duration_ms,
                       report->min_distance_mm, report->max_distance_mm);
  }
};

// The facade: one call, three subsystems coordinated in order.
class BenchRunFacade {
 public:
  [[nodiscard]] std::string summarize(std::string_view raw_log) const {
    const std::vector<Sample> samples = parser_.parse(raw_log);
    const std::optional<Report> report = stats_.analyze(samples);
    return writer_.format(report);
  }

 private:
  RunParser parser_;
  RunStats stats_;
  ReportWriter writer_;
};

int main() {
  constexpr std::string_view raw_log = "0,1200\n1000,1180\n2000,1150\n3000,1205\n4000,1140";

  const BenchRunFacade facade;
  std::cout << facade.summarize(raw_log) << '\n';
  std::cout << facade.summarize("") << '\n';

  // A caller who wants the samples themselves, not the formatted line, calls the subsystems directly.
  const RunParser parser;
  const RunStats stats;
  const std::vector<Sample> samples = parser.parse(raw_log);
  const std::optional<Report> report = stats.analyze(samples);
  std::cout << std::format("parsed {} samples directly, max distance {} mm\n", samples.size(),
                           report->max_distance_mm);
}

#include <format>
#include <iostream>

class PowerBus {
 public:
  [[nodiscard]] bool energize() {
    energized_ = true;
    return true;
  }
  [[nodiscard]] bool energized() const { return energized_; }

 private:
  bool energized_ = false;
};

class SensorBus {
 public:
  explicit SensorBus(const PowerBus& power) : power_(power) {}
  [[nodiscard]] bool start() {
    if (!power_.energized()) return false;
    started_ = true;
    return true;
  }
  [[nodiscard]] bool started() const { return started_; }

 private:
  const PowerBus& power_;
  bool started_ = false;
};

class MotionController {
 public:
  explicit MotionController(const SensorBus& sensors) : sensors_(sensors) {}
  [[nodiscard]] bool arm() {
    if (!sensors_.started()) return false;
    armed_ = true;
    return true;
  }
  [[nodiscard]] bool armed() const { return armed_; }

 private:
  const SensorBus& sensors_;
  bool armed_ = false;
};

// A later sprint added a getter so a calibration tool could reach one subsystem. The order the
// facade exists to enforce is now something every caller has to remember on their own.
class RobotFacade {
 public:
  RobotFacade() : sensors_(power_), motion_(sensors_) {}
  [[nodiscard]] bool bring_up() {
    if (!power_.energize()) return false;
    if (!sensors_.start()) return false;
    return motion_.arm();
  }
  [[nodiscard]] MotionController& motion() { return motion_; }

 private:
  PowerBus power_;
  SensorBus sensors_;
  MotionController motion_;
};

int main() {
  RobotFacade facade;
  std::cout << std::format("calibration tool arms the motion controller directly: {}\n", facade.motion().arm());
  std::cout << std::format("bring_up(), asked for afterward:                     {}\n", facade.bring_up());
}
